// lib/agent/occupations.ts — jobs beyond hospitality, for the job search and the ranking (shared by
// the browser and the server; hospitality families live in titles.ts). Each family is one job: every
// way employers write it (English, French, Arabic, German, abbreviations), its level (1 entry …
// 7 executive), the titles worth searching, neighbouring jobs and the industries it belongs to.
//
// `parent` makes a family a kind of a broader job: a cardiologist is a doctor, a civil engineer an
// engineer. A search for the broader job counts every kind of it; a search for one kind counts only
// that kind, and offers the broader job as related. Titles that also mean something else ("model",
// "architect", "advocate", "driver", "trainer") are `ambiguous` and need their `context`.
//
// Adding a job: add a family here; scripts/check-search.ts reports titles claimed by two families.

import type { Family, Industry } from "./titles";

const fam = (id: string, level: number, industries: Industry[], titles: string[], o: Partial<Family> = {}): Family =>
  ({ id, level, industries, titles, ...o });

/** A medical specialty: a kind of doctor, written as the specialist or as "<field> specialist". */
function specialty(id: string, nouns: string[], fields: string[], fr: string[], ar: string[], de: string[] = []): Family {
  const forms = fields.flatMap(x => [`${x} specialist`, `specialist ${x}`, `consultant ${x}`, `${x} consultant`, `${x} physician`, `${x} doctor`]);
  return fam(id, 2, ["healthcare"], [...nouns, ...forms, ...fr, ...ar, ...de], {
    parent: "doctor", search: [nouns[0]], fr: fr.slice(0, 1), de: de.slice(0, 1), related: ["doctor"],
  });
}

/** A teacher of one subject or stage: a kind of teacher. */
function teaching(id: string, en: string[], fr: string[], ar: string[], de: string[] = []): Family {
  return fam(id, 2, ["education"], [...en, ...fr, ...ar, ...de], { parent: "teacher", search: [en[0]], fr: fr.slice(0, 1), de: de.slice(0, 1), related: ["teacher"] });
}

